schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/agency-pricing-tiers.json",
  "title": "Agency Pricing Tiers playbook step",
  "type": "object",
  "required": ["currency", "tiers", "fence", "default_recommendation", "presentation", "scope_up", "concessions", "steps"],
  "additionalProperties": false,
  "definitions": {
    "money": {"type": "number", "minimum": 0},
    "deliverable": {
      "type": "object",
      "required": ["name", "quantity", "turnaround_days"],
      "additionalProperties": false,
      "properties": {
        "name": {"type": "string", "minLength": 3},
        "quantity": {"type": "integer", "minimum": 1},
        "turnaround_days": {"type": "integer", "minimum": 1}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "currency": {"type": "string", "pattern": "^[A-Z]{3}$"},
    "tiers": {
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "items": [
        {"properties": {"name": {"const": "good"}}},
        {"properties": {"name": {"const": "better"}}},
        {"properties": {"name": {"const": "best"}}}
      ],
      "allOf": [{
        "items": {
          "type": "object",
          "required": ["name", "price", "delivery_cost", "gross_margin_abs", "gross_margin_pct", "deliverables"],
          "additionalProperties": false,
          "properties": {
            "name": {"type": "string", "enum": ["good", "better", "best"]},
            "price": {"type": "number", "exclusiveMinimum": 0},
            "delivery_cost": {
              "type": "object",
              "required": ["hours", "loaded_hourly_cost", "pass_through"],
              "additionalProperties": false,
              "properties": {
                "hours": {"type": "number", "exclusiveMinimum": 0},
                "loaded_hourly_cost": {"type": "number", "exclusiveMinimum": 0},
                "pass_through": {"$ref": "#/definitions/money"}
              }
            },
            "gross_margin_abs": {"type": "number"},
            "gross_margin_pct": {"type": "number", "maximum": 1},
            "deliverables": {"type": "array", "minItems": 1, "items": {"$ref": "#/definitions/deliverable"}}
          }
        }
      }]
    },
    "gap_justification": {
      "type": "object",
      "required": ["scope_difference"],
      "additionalProperties": false,
      "properties": {"scope_difference": {"type": "string", "minLength": 10}}
    },
    "fence": {
      "type": "object",
      "required": ["omitted_deliverable", "needed_for", "named_on_rate_sheet"],
      "additionalProperties": false,
      "properties": {
        "omitted_deliverable": {"type": "string", "minLength": 3},
        "needed_for": {"type": "string", "minLength": 10},
        "named_on_rate_sheet": {"const": true}
      }
    },
    "default_recommendation": {"const": "better"},
    "presentation": {
      "type": "object",
      "required": ["order", "prices_visible"],
      "additionalProperties": false,
      "properties": {
        "order": {"type": "array", "minItems": 3, "maxItems": 3, "items": [{"const": "best"}, {"const": "better"}, {"const": "good"}]},
        "prices_visible": {"const": true}
      }
    },
    "scope_up": {
      "type": "object",
      "required": ["trigger", "price_rule", "approver", "written_confirmation_required", "free_goodwill_allowed"],
      "additionalProperties": false,
      "properties": {
        "trigger": {"type": "string", "minLength": 10},
        "price_rule": {"const": "difference between the two tier prices pro-rated to the remaining term"},
        "approver": {"type": "string", "minLength": 3},
        "written_confirmation_required": {"const": true},
        "free_goodwill_allowed": {"const": false}
      }
    },
    "concessions": {
      "type": "object",
      "required": ["method", "published_prices_vary_by_client"],
      "additionalProperties": false,
      "properties": {
        "method": {"const": "remove_named_deliverable_or_quantity"},
        "published_prices_vary_by_client": {"const": false}
      }
    },
    "steps": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["id", "name", "exit_criterion", "output_location"],
        "additionalProperties": false,
        "properties": {
          "id": {"type": "string", "pattern": "^s[0-9]+$"},
          "name": {"type": "string", "minLength": 3},
          "exit_criterion": {"type": "string", "minLength": 10, "not": {"pattern": "^(?i:shipped|reviewed|signoff|done)$"}},
          "output_location": {"type": "string", "minLength": 3}
        }
      }
    }
  }
}

output-contract.example:
{
  "currency": "EUR",
  "tiers": [
    {
      "name": "good", "price": 3000,
      "delivery_cost": {"hours": 20, "loaded_hourly_cost": 90, "pass_through": 200},
      "gross_margin_abs": 1000, "gross_margin_pct": 0.333,
      "deliverables": [
        {"name": "paid search campaigns managed", "quantity": 2, "turnaround_days": 5},
        {"name": "monthly performance report", "quantity": 1, "turnaround_days": 3}
      ]
    },
    {
      "name": "better", "price": 5000,
      "delivery_cost": {"hours": 28, "loaded_hourly_cost": 90, "pass_through": 300},
      "gross_margin_abs": 2180, "gross_margin_pct": 0.436,
      "deliverables": [
        {"name": "paid search campaigns managed", "quantity": 4, "turnaround_days": 3},
        {"name": "monthly performance report", "quantity": 1, "turnaround_days": 2},
        {"name": "conversion tracking setup", "quantity": 1, "turnaround_days": 10},
        {"name": "weekly optimisation call", "quantity": 4, "turnaround_days": 7}
      ]
    },
    {
      "name": "best", "price": 8000,
      "delivery_cost": {"hours": 36, "loaded_hourly_cost": 90, "pass_through": 400},
      "gross_margin_abs": 4360, "gross_margin_pct": 0.545,
      "deliverables": [
        {"name": "paid search campaigns managed", "quantity": 8, "turnaround_days": 2},
        {"name": "monthly performance report", "quantity": 1, "turnaround_days": 1},
        {"name": "conversion tracking setup", "quantity": 1, "turnaround_days": 5},
        {"name": "weekly optimisation call", "quantity": 4, "turnaround_days": 7},
        {"name": "landing page A/B test", "quantity": 2, "turnaround_days": 14}
      ]
    }
  ],
  "fence": {"omitted_deliverable": "conversion tracking setup", "needed_for": "an e-commerce ICP cannot report ROAS without conversion tracking", "named_on_rate_sheet": true},
  "default_recommendation": "better",
  "presentation": {"order": ["best", "better", "good"], "prices_visible": true},
  "scope_up": {
    "trigger": "client requests a deliverable or quantity outside the current tier's list",
    "price_rule": "difference between the two tier prices pro-rated to the remaining term",
    "approver": "account director",
    "written_confirmation_required": true,
    "free_goodwill_allowed": false
  },
  "concessions": {"method": "remove_named_deliverable_or_quantity", "published_prices_vary_by_client": false},
  "steps": [
    {"id": "s1", "name": "cost every tier", "exit_criterion": "best gross margin is the highest in EUR and percent: 4360 / 54.5 percent against 2180 / 43.6 and 1000 / 33.3", "output_location": "pricing/2026-05-rate-sheet.md"},
    {"id": "s2", "name": "publish best-first rate sheet", "exit_criterion": "rate sheet lists best, better, good with prices visible and the fence named under good", "output_location": "pricing/2026-05-rate-sheet.md"},
    {"id": "s3", "name": "brief account managers on scope-up", "exit_criterion": "every account manager can state trigger, price rule and approver; first scope-up logged with written confirmation", "output_location": "pricing/scope-up-log.md"}
  ]
}

